-- Same TEST investor journey: remove duplicate retained-signature display work.
-- Contract B3014CDBBD739D7EAEA0F8D9A2FA36D58957A3FE0525EE8441B84D357D40A1D3.
-- No authority helper, writer, timeout or final fresh package check is changed.
do $evidence_projection_read$
declare
  target constant oid:=30039;
  original constant text:=$evidence_projection_original$
  select case when q.offering_revision_id is null then null else pg_catalog.jsonb_build_object(
    'profile',q.profile,'state',bx1_private.offering_document_readiness(target_revision),'manifest_id',m.id,
    'manifest_hash',m.hash,'version',2,'signature_status',case
      when bx1_private.offering_signature_admitted() is not true then 'NOT_ADMITTED'
      when exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id
        where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id)) then 'EVIDENCE_RETAINED'
      when exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id
        where au.revision_id=target_revision and op.state='RECOVERY_REQUIRED') then 'RECOVERY_REQUIRED'
      when exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id
        where au.revision_id=target_revision and (op.noncurrent_reason is not null or not bx1_private.offering_signature_authorisation_current(au.id))) then 'NON_CURRENT'
      when exists(select 1 from bx1_private.offering_signature_operations op join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id
        where au.revision_id=target_revision) then 'PENDING'
      when exists(select 1 from bx1_private.offering_signature_authorisations au where au.revision_id=target_revision
        and bx1_private.offering_signature_authorisation_current(au.id)) then 'SIGNATURE_REQUIRED' else 'PURPOSE_REQUIRED' end,
    'approval_allowed',exists(select 1 from bx1_private.offering_signature_operations op
      join bx1_private.offering_signature_authorisations au on au.id=op.authorisation_id
      where au.revision_id=target_revision and bx1_private.offering_signature_evidence_current(op.id))) end
    from (select 1) base left join bx1_private.offering_document_profiles q on q.offering_revision_id=target_revision
    left join bx1_private.offering_document_manifests m on m.offering_revision_id=target_revision;
$evidence_projection_original$;
