"-","proargmodes":null,"proargnames":["c","target_revision"],"proargtypes":["3802","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"22414","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"oid":"30044","sha":"10da13532759fdd5360b4bc1e8dc952af40f0c77071c55fd783dbb589ca41bc6","metadata":{"oid":"30044","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"offering_document_replacement_recipes","prorows":0,"pronargs":0,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"22414","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"oid":"30335","sha":"d25a8baf9e630915ef2df083f152389c4378610a2bc9af2c66ef58db04c6e0c3","metadata":{"oid":"30335","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"offering_workflow_read_scoped_pre_test_workspace","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["c"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"24138","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"oid":"30718","sha":"45c211e333c18904bef2bf0a059c8e4816d985f27e791b3e97f67bc6fe58789c","metadata":{"oid":"30718","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"offering_signature_admitted","prorows":0,"pronargs":0,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"22414","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"oid":"30720","sha":"0f463382e6e285429545fb074710c30402cfc828ce66d5cf834f427f73b9bfd5","metadata":{"oid":"30720","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"offering_signature_authorisation_current","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_id"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"22414","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"oid":"30721","sha":"d3b9130af57762a05311b4c1b8048ca580db3136fa59e3f00deb2e6de2a4c483","metadata":{"oid":"30721","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"offering_signature_evidence_current","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_operation"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"22414","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}}]$evidence_projection_dependencies$::jsonb;
  expected_relations constant jsonb:=$evidence_projection_relations${"columns":[{"attacl":null,"attlen":16,"attnum":1,"attname":"offering_revision_id","attalign":"c","attbyval":false,"attndims":0,"attrelid":"29727","atttypid":"2950","atthasdef":false,"atttypmod":-1,"attislocal":true,"attnotnull":true,"attoptions":null,"attstorage":"p","attcacheoff":-1,"attidentity":"","attinhcount":0,"attcollation":"0","attgenerated":"","attisdropped":false,"attfdwoptions":null,"atthasmissing":false,"attmissingval":null,"attstattarget":null,"attcompression":""},{"attacl":null,"attlen":16,"attnum":2,"attname":"offering_revision_id","attalign":"c","attbyval":false,"attndims":0,"attrelid":"29947","atttypid":"2950","atthasdef":false,"atttypmod":-1,"attislocal":true,"attnotnull":true,"attoptions":null,"attstorage":"p","attcacheoff":-1,"attidentity":"","attinhcount":0,"attcollation":"0","attgenerated":"","attisdropped":false,"attfdwoptions":null,"atthasmissing":false,"attmissingval":null,"attstattarget":null,"attcompression":""}],"indexes":[{"indkey":[1],"indpred":null,"indclass":["10065"],"indexprs":null,"indnatts":1,"indrelid":"29727","indislive":true,"indoption":[0],"indexrelid":"29736","indisready":true,"indisvalid":true,"indisunique":true,"indnkeyatts":1,"indcheckxmin":false,"indcollation":["0"],"indimmediate":true,"indisprimary":true,"indisclustered":false,"indisexclusion":false,"indisreplident":false,"indnullsnotdistinct":false},{"indkey":[2,1],"indpred":null,"indclass":["10065","10065"],"indexprs":null,"indnatts":2,"indrelid":"29727","indislive":true,"indoption":[0,0],"indexrelid":"29738","indisready":true,"indisvalid":true,"indisunique":true,"indnkeyatts":2,"indcheckxmin":false,"indcollation":["0","0"],"indimmediate":true,"indisprimary":false,"indisclustered":false,"indisexclusion":false,"indisreplident":false,"indnullsnotdistinct":false},{"indkey":[1],"indpred":null,"indclass":["10065"],"indexprs":null,"indnatts":1,"indrelid":"29947","indislive":true,"indoption":[0],"indexrelid":"29957","indisready":true,"indisvalid":true,"indisunique":true,"indnkeyatts":1,"indcheckxmin":false,"indcollation":["0"],"indimmediate":true,"indisprimary":true,"indisclustered":false,"indisexclusion":false,"indisreplident":false,"indnullsnotdistinct":false},{"indkey":[2],"indpred":null,"indclass":["10065"],"indexprs":null,"indnatts":1,"indrelid":"29947","indislive":true,"indoption":[0],"indexrelid":"29959","indisready":true,"indisvalid":true,"indisunique":true,"indnkeyatts":1,"indcheckxmin":false,"indcollation":["0"],"indimmediate":true,"indisprimary":false,"indisclustered":false,"indisexclusion":false,"indisreplident":false,"indnullsnotdistinct":false}],"constraints":[{"oid":"29737","conbin":null,"conkey":[1],"confkey":null,"conname":"offering_document_profiles_pkey","contype":"p","conindid":"29736","conrelid":"29727","contypid":"0","conexclop":null,"conffeqop":null,"confrelid":"0","conpfeqop":null,"conppeqop":null,"conislocal":true,"condeferred":false,"confdeltype":" ","confupdtype":" ","coninhcount":0,"conparentid":"0","connamespace":"22414","connoinherit":true,"convalidated":true,"condeferrable":false,"confmatchtype":" ","confdelsetcols":null},{"oid":"29739","conbin":null,"conkey":[2,1],"confkey":null,"conname":"offering_document_profiles_product_id_offering_revision_id_key","contype":"u","conindid":"29738","conrelid":"29727","contypid":"0","conexclop":null,"conffeqop":null,"confrelid":"0","conpfeqop":null,"conppeqop":null,"conislocal":true,"condeferred":false,"confdeltype":" ","confupdtype":" ","coninhcount":0,"conparentid":"0","connamespace":"22414","connoinherit":true,"convalidated":true,"condeferrable":false,"confmatchtype":" ","confdelsetcols":null},{"oid":"29958","conbin":null,"conkey":[1],"confkey":null,"conname":"offering_document_manifests_pkey","contype":"p","conindid":"29957","conrelid":"29947","contypid":"0","conexclop":null,"conffeqop":null,"confrelid":"0","conpfeqop":null,"conppeqop":null,"conislocal":true,"condeferred":false,"confdeltype":" ","confupdtype":" ","coninhcount":0,"conparentid":"0","connamespace":"22414","connoinherit":true,"convalidated":true,"condeferrable":false,"confmatchtype":" ","confdelsetcols":null},{"oid":"29960","conbin":null,"conkey":[2],"confkey":null,"conname":"offering_document_manifests_offering_revision_id_key","contype":"u","conindid":"29959","conrelid":"29947","contypid":"0","conexclop":null,"conffeqop":null,"confrelid":"0","conpfeqop":null,"conppeqop":null,"conislocal":true,"condeferred":false,"confdeltype":" ","confupdtype":" ","coninhcount":0,"conparentid":"0","connamespace":"22414","connoinherit":true,"convalidated":true,"condeferrable":false,"confmatchtype":" ","confdelsetcols":null}]}$evidence_projection_relations$::jsonb;
  dependency jsonb; cut jsonb; metadata jsonb; actual_relations jsonb;
  next_body text:=original; restored text; definition text; stage integer;
begin
  if current_user<>'postgres' or session_user<>'postgres' or auth.uid() is not null
    or bx1_private.test_roleplay_environment() is not true
    or not exists(select 1 from bx1_portal.entry_configuration where singleton and environment='TESTNET') then
    raise exception 'evidence_projection_test_owner_required' using errcode='42501';end if;
  if pg_catalog.to_regprocedure('bx1_private.offering_document_evidence_summary(uuid)') is distinct from target
    or encode(sha256(convert_to(original,'UTF8')),'hex') is distinct from original_sha
    or jsonb_array_length(cuts)<>3 then
    raise exception 'evidence_projection_original_pin_changed' using errcode='55000';end if;
  for cut in select value from jsonb_array_elements(cuts) loop
    if (length(next_body)-length(replace(next_body,cut->>'from','')))/length(cut->>'from')<>1 then
      raise exception 'evidence_projection_forward_cut_not_unique: %',cut->>'name' using errcode='55000';end if;
    next_body:=replace(next_body,cut->>'from',cut->>'to');
  end loop;
  restored:=next_body;
  for cut in select value from jsonb_array_elements(cuts) with ordinality item(value,position) order by position desc loop
    if (length(restored)-length(replace(restored,cut->>'to','')))/length(cut->>'to')<>1 then
      raise exception 'evidence_projection_reverse_cut_not_unique: %',cut->>'name' using errcode='55000';end if;
    restored:=replace(restored,cut->>'to',cut->>'from');
  end loop;
  if restored is distinct from original
    or (length(next_body)-length(replace(next_body,'bx1_private.offering_signature_evidence_current(op.id)','')))
      /length('bx1_private.offering_signature_evidence_current(op.id)')<>1 then
    raise exception 'evidence_projection_inverse_or_single_evaluation_failed' using errcode='55000';end if;
  -- Check the unchanged call graph and existing profile/manifest cardinality on
  -- both sides. No dependency function or relation is created or changed.
  for stage in 1..2 loop
    for dependency in select value from jsonb_array_elements(dependencies) loop
      select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=(dependency->>'oid')::oid;
      if metadata is null or metadata-'prosrc' is distinct from dependency->'metadata'
        or encode(sha256(convert_to(metadata->>'prosrc','UTF8')),'hex') is distinct from dependency->>'sha' then
        raise exception 'evidence_projection_dependency_changed: %',dependency->>'oid' using errcode='55000';end if;
    end loop;
    select jsonb_build_object(
      'constraints',(select coalesce(jsonb_agg(to_jsonb(c) order by c.oid),'[]'::jsonb)
        from pg_catalog.pg_constraint c where c.conrelid in ('bx1_private.offering_document_profiles'::regclass,
          'bx1_private.offering_document_manifests'::regclass) and c.contype in ('p','u')),
      'indexes',(select coalesce(jsonb_agg(to_jsonb(i) order by i.indexrelid),'[]'::jsonb)
        from pg_catalog.pg_index i where i.indexrelid in (29736,29738,29957,29959)),
      'columns',(select coalesce(jsonb_agg(to_jsonb(a) order by a.attrelid,a.attnum),'[]'::jsonb)
        from pg_catalog.pg_attribute a where a.attrelid in ('bx1_private.offering_document_profiles'::regclass,
          'bx1_private.offering_document_manifests'::regclass) and a.attname='offering_revision_id')) into actual_relations;
    if actual_relations is distinct from expected_relations then
      raise exception 'evidence_projection_profile_manifest_cardinality_changed' using errcode='55000';end if;
    select to_jsonb(p) into metadata from pg_catalog.pg_proc p where p.oid=target;
    if metadata is null or metadata-'prosrc' is distinct from expected_metadata then
      raise exception 'evidence_projection_target_metadata_changed' using errcode='55000';end if;
    if stage=1 then
      if metadata->>'prosrc' is distinct from original and metadata->>'prosrc' is distinct from next_body then
        raise exception 'evidence_projection_unexpected_source' using errcode='55000';end if;
      if metadata->>'prosrc'=original then
        definition:=pg_catalog.pg_get_functiondef(target);
        if (length(definition)-length(replace(definition,original,'')))/length(original)<>1 then
          raise exception 'evidence_projection_definition_not_unique' using errcode='55000';end if;
        execute replace(definition,original,next_body);
      end if;
    elsif metadata->>'prosrc' is distinct from next_body then
      raise exception 'evidence_projection_target_preservation_failed' using errcode='55000';end if;
  end loop;
end $evidence_projection_read$;
